/* @socom-skeleton body AddVisual__Q23zdb5CNodeFPQ23zdb7CVisual */
namespace zdb {
bool CNode::AddVisual(CVisual* visual)
	{
		if (visual && !m_visual.Exists(visual))
		{
			visual->m_refcount++;
			m_visual.insert(m_visual.begin(), visual);

			SetParentHasVisuals();

			return true;
		}

		return false;
	}
}

