/* @socom-skeleton body DeleteVisuals__Q23zdb5CNodeFv */
namespace zdb {
s32 CNode::DeleteVisuals()
	{
		for (auto i = m_visual.begin(); i != m_visual.end(); ++i)
		{
			(*i)->Release();
			delete (*i);
		}

		m_visual.clear();
		m_hasVisuals = false;

		return 0;
	}
}

