/* @socom-skeleton body AddChild__Q23zdb5CNodeFPQ23zdb5CNode */
namespace zdb {
void CNode::AddChild(CNode* node)
	{
		CNode* parent = node->m_parent;
		if (node && parent != this)
		{
			CNode* child = node;
			if (m_type != (u32)TYPE::CHILD)
			{
				if (parent)
				{
					parent->DeleteChild(node);
				}

				child->m_parent = this;
				child->m_count++;
			}

			if (m_count == m_child.size() && 1000 < m_count)
			{
				m_child.reserve(m_count + 100);
			}

			m_child.insert(m_child.begin(), child);
		}
	}
}

/* @socom-skeleton body DeleteChild__Q23zdb5CNodeFPQ23zdb5CNode */
namespace zdb {
s32 CNode::DeleteChild(CNode* child)
	{
		s32 count = child->m_count;

		if (m_child.Exists(child))
		{
			if (m_type == (u32)TYPE::CHILD)
			{
				m_child.Remove(child);
				count = -1;
				m_flatten = true;
			}
			else
			{
				child->m_count--;

				if (child->m_count < 0)
				{
					child->m_count = 0;
				}

				count = child->m_count;

				m_child.Remove(child);

				child->m_parent = NULL;

				m_flatten = true;
			}
		}
		
		return 0;
	}
}

/* @socom-skeleton body FindChild__Q23zdb5CNodeFPCcb */
namespace zdb {
CNode* CNode::FindChild(const char* name, bool nested)
	{
		if (!name)
			return NULL;

		zdb::CNode* child = NULL;
		size_t length = strlen(name);

		for (auto i = m_child.begin(); i != m_child.end(); ++i)
		{
			child = *i;

			size_t childStringLength = strlen(child->m_name);

			if (length == childStringLength && strcmp(child->m_name, name) == 0)
				return *i;
		}

		if (nested)
		{
			for (auto i = m_child.begin(); i != m_child.end(); i++)
			{
				child = *i;
				size_t childStringLength = strlen(child->m_name);

				if (length == childStringLength && strcmp(child->m_name, name) == 0)
					return child->FindChild(name, nested);
			}
		}

		return NULL;
	}
}

/* @socom-skeleton body FindChild__Q23zdb5CNodeFPQ23zdb5CNodeb */
namespace zdb {
CNode* CNode::FindChild(CNode* child, bool nested)
	{
		/* 0x227430: a direct child, else (nested) the first hit in each child's subtree */
		if (!child)
			return NULL;

		for (auto i = m_child.begin(); i != m_child.end(); ++i)
		{
			if (*i == child)
				return *i;
		}

		CNode* found = NULL;

		if (nested)
		{
			for (auto i = m_child.begin(); found == NULL && i != m_child.end(); ++i)
				found = (*i)->FindChild(child, true);
		}

		return found;
	}
}

