void CNode::SetPosition(f32 x, f32 y, f32 z)
	{
		m_matrix.m_matrix[3][0] = x;
		m_matrix.m_matrix[3][1] = y;
		m_matrix.m_matrix[3][2] = z;

		UpdateGrid();
		m_modified = true;

		if (m_nodeEx)
		{
			m_nodeEx->OnMove(this);
		}
	}
