namespace zdb {
void CNode::SetName(const char* name)
	{
		char* str = m_name;

		if (str && str != UNNAMED_NODE)
		{
			zfree(str);
		}

		str = const_cast<char*>(UNNAMED_NODE);

		if (name)
		{
			str = zstrdup(name);
		}

		m_name = str;
	}
}

