/* @socom-skeleton body AddDI__Q23zdb5CNodeFPQ23zdb3CDI */
namespace zdb {
bool CNode::AddDI(CDI* di)
	{
		if (di && !m_di.Exists(di))
		{
			di->m_refcount++;
			m_di.insert(m_di.begin(), di);
			m_modified = true;

			return true;
		}

		return false;
	}
}

